# Sourced at the top of every jobs/final/*.pbs script. P3_ROOT, P3_DATA and P3_RESULTS come from qsub -v
# (scripts/final_submit.sh sets them). No queue is requested anywhere: Vanda routes the job (advice of Prof. Chen).
set -o pipefail
: "${P3_ROOT:?P3_ROOT not set (submit with scripts/final_submit.sh)}"
source "$P3_ROOT/scripts/env.sh"
source "$P3_ROOT/scripts/run_lib.sh"
source "$P3_ROOT/scripts/final_lib.sh"
cd "$P3_ROOT"
mkdir -p "$P3_RESULTS"
# Extra graphs generated by this suite (edge-factor sweep) live in the submitting user's own scratch.
export P3_EXTRA=${P3_EXTRA:-/scratch/$USER/p3extra}
mkdir -p "$P3_EXTRA"
# val/ holds web-Google vectors only (tools/validate.py compares every *.bin in it with val/serial.bin);
# vectors of the LiveJournal 50-iteration validation go to valscale/ (compared by tools/compare_vec.py).
VS=$P3_RESULTS/valscale
LJ=$P3_DATA/soc-LiveJournal1.bin
FR=$P3_DATA/com-friendster.bin
GG=$P3_DATA/web-Google.bin
